import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

type PhyllotaxisProps = {
  /** Number of seeds. */
  count?: number;
  /** Seed size multiplier. */
  size?: number;
  /** Frames for all seeds to spiral out. */
  growFrames?: number;
  /** Frames per pulse along the accent arm once grown. */
  pulseFrames?: number;
  /** Arm spacing: every n-th seed forms one parastichy (a Fibonacci number reads best). */
  arm?: number;
  /** Slow rotation of the head in degrees per second; 0 holds still. */
  rotation?: number;
  speed?: number;
  background?: string;
  color?: string;
  accent?: string;
};

const phyllotaxisDefaults: Required<PhyllotaxisProps> = {
  count: 420,
  size: 1,
  growFrames: 60,
  pulseFrames: 45,
  arm: 21,
  rotation: 4,
  speed: 1,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
};

const GOLDEN = (137.508 * Math.PI) / 180;
const POP = 10;
const pop = Easing.out(Easing.back(2.2));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const fmt = (n: number) => Math.round(n * 10) / 10;
const dot = (x: number, y: number, r: number) =>
  `M ${fmt(x - r)} ${fmt(y)} a ${fmt(r)} ${fmt(r)} 0 1 0 ${fmt(r * 2)} 0 a ${fmt(r)} ${fmt(r)} 0 1 0 ${fmt(-r * 2)} 0 `;

function PhyllotaxisBase({
  count = phyllotaxisDefaults.count,
  size = phyllotaxisDefaults.size,
  growFrames = phyllotaxisDefaults.growFrames,
  pulseFrames = phyllotaxisDefaults.pulseFrames,
  arm = phyllotaxisDefaults.arm,
  rotation = phyllotaxisDefaults.rotation,
  speed = phyllotaxisDefaults.speed,
  background = phyllotaxisDefaults.background,
  color = phyllotaxisDefaults.color,
  accent = phyllotaxisDefaults.accent,
}: PhyllotaxisProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const n = Math.max(1, Math.round(count));
  const step = Math.max(1, Math.round(arm));
  const time = frame * speed;
  const cx = width / 2;
  const cy = height / 2;
  const maxR = Math.min(width, height) * 0.44;
  const c = maxR / Math.sqrt(n);
  const spin = (rotation * Math.PI * time) / 180 / fps;

  // Seeds appear in order with a little overshoot; the reveal eases so the
  // dense centre does not flash in all at once.
  const grown = (i: number) => {
    const at = growFrames * Math.sqrt(i / n);
    return pop(Math.min(1, Math.max(0, (time - at) / POP)));
  };
  const armIn = interpolate(time, [growFrames, growFrames + 14], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const since = time - growFrames - 10;
  const pulse = since > 0 ? (since / Math.max(1, pulseFrames)) % 1 : -1;

  let plain = "";
  let red = "";
  let spine = "";
  for (let i = 1; i <= n; i++) {
    const s = grown(i);
    if (s <= 0) continue;
    const radius = c * Math.sqrt(i);
    const theta = i * GOLDEN + spin;
    const x = cx + Math.cos(theta) * radius;
    const y = cy + Math.sin(theta) * radius;
    // Outer seeds are a touch larger, like a sunflower head.
    const base = c * 0.42 * size * (0.55 + 0.45 * Math.sqrt(i / n));
    const onArm = i % step === 0 && armIn > 0;
    if (!onArm) {
      plain += dot(x, y, base * s);
      continue;
    }
    // Pulse travels outward along the arm as a soft gaussian bump.
    const u = Math.sqrt(i / n);
    const bump =
      pulse >= 0 ? Math.exp(-(((u - pulse * 1.4 + 0.2) / 0.09) ** 2)) : 0;
    red += dot(x, y, base * s * (1 + 0.25 * armIn + bump * 0.9));
    spine += `${spine ? "L" : "M"} ${fmt(x)} ${fmt(y)} `;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: background }}>
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="PhyllotaxisBase spiral"
        style={{ display: "block" }}
      >
        <path d={plain} fill={color} />
        {spine ? (
          <path
            d={spine}
            fill="none"
            stroke={accent}
            strokeOpacity={0.35 * armIn}
            strokeWidth={Math.min(width, height) / 720}
          />
        ) : null}
        <path d={red} fill={color} fillOpacity={1 - armIn} />
        <path d={red} fill={accent} fillOpacity={armIn} />
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  count: {
    type: "number",
    default: 420,
    min: 50,
    max: 1200,
    step: 10,
    description: "Seeds",
    hiddenFromList: false,
  },
  size: {
    type: "number",
    default: 1,
    min: 0.3,
    max: 2,
    step: 0.05,
    description: "Seed size",
    hiddenFromList: false,
  },
  arm: {
    type: "number",
    default: 21,
    min: 1,
    max: 89,
    step: 1,
    description: "Arm spacing",
    hiddenFromList: false,
  },
  growFrames: {
    type: "number",
    default: 60,
    min: 15,
    max: 150,
    step: 5,
    description: "Grow frames",
    hiddenFromList: false,
  },
  pulseFrames: {
    type: "number",
    default: 45,
    min: 15,
    max: 120,
    step: 5,
    description: "Pulse frames",
    hiddenFromList: false,
  },
  rotation: {
    type: "number",
    default: 4,
    min: -30,
    max: 30,
    step: 1,
    description: "Rotation °/s",
    hiddenFromList: false,
  },
  background: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  color: {
    type: "color",
    default: "#FFFFFF",
    description: "Seeds",
  },
  accent: {
    type: "color",
    default: "#E5322D",
    description: "Arm",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["count","size","arm","growFrames","pulseFrames","rotation","background","color","accent","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  count: 420,
  size: 1,
  arm: 21,
  growFrames: 60,
  pulseFrames: 45,
  rotation: 4,
  background: "#111111",
  color: "#FFFFFF",
  accent: "#E5322D",
  speed: 1,
};

type PhyllotaxisElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PhyllotaxisBase>;

const PhyllotaxisInner = forwardRef<
  HTMLDivElement,
  PhyllotaxisElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Phyllotaxis>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PhyllotaxisBase
          {...(componentProps as unknown as ComponentProps<typeof PhyllotaxisBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Phyllotaxis = Interactive.withSchema({
  Component: PhyllotaxisInner,
  componentName: "<Phyllotaxis>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
